<?= $this->extend('layouts/public') ?><?= $this->section('contenido') ?><section class="account-heading"><div><p>Mi cuenta</p><h1>Mis entradas</h1><span>Hola, <?= esc($usuario['nombre']) ?>. Consulta tus reservas y entradas confirmadas.</span></div></section>
